#!/usr/bin/env bash
# This code has been fully generated by an AI.
# Category coverage: generic updater, phase-aware exec hook, generator output.
set -euo pipefail
source "$(cd -- "$(dirname -- "${BASH_SOURCE[0]}")" && pwd)/../../scripts/common.sh"

build_semrel
PROV=$(build_plugin provider-git provider-git)
REPLACE=$(build_plugin updater-replace updater-replace)
EXEC=$(build_plugin hook-exec hook-exec)

REPO=$(new_scenario_repo "26-updater-replace-hook-exec")

REMOTE_DIR="$WORK_DIR/26-remote.git"
rm -rf "$REMOTE_DIR"
git init -q --bare -b main "$REMOTE_DIR"
git -C "$REPO" remote add origin "$REMOTE_DIR"

mkdir -p "$REPO/docs/archive"
printf 'version-0.1.0\n' > "$REPO/README.md"
printf 'version-0.1.0\n' > "$REPO/docs/guide.md"
printf 'version-0.1.0\n' > "$REPO/docs/archive/old.md"
printf 'ARG VERSION=0.1.0\n' > "$REPO/Dockerfile"
commit_all "$REPO" "chore: initial files"
git -C "$REPO" tag v0.1.0
git -C "$REPO" push -q origin main --tags

printf 'feature\n' > "$REPO/feature.txt"
git -C "$REPO" add feature.txt
git -C "$REPO" commit -q -m "feat: exercise generic plugins"

cat > "$REPO/.semrel.yaml" <<EOF
schemaVersion: 1
tagPrefix: "v"
branches:
  - name: main
rules:
  - type: feat
    bump: minor
plugins:
  - path: "$EXEC"
    phase: generator
    args:
      generateNotesCmd: 'printf "exec notes for %s" "\$SEMREL_VERSION"'
      phase: generator
  - path: "$REPLACE"
    phase: pre-tag
    args:
      replacements: |
        - files: ["README.md", "docs/**/*.md"]
          ignore: ["docs/archive/**"]
          from: 'version-\\d+\\.\\d+\\.\\d+'
          to: 'version-\${nextRelease.version}'
          results:
            - file: README.md
              hasChanged: true
              numMatches: 1
              numReplacements: 1
        - files: Dockerfile
          from: '^ARG VERSION=.*$'
          flags: m
          to: 'ARG VERSION=\${nextRelease.version}'
  - path: "$EXEC"
    phase: pre-tag
    args:
      cmd: 'printf "%s" "\$SEMREL_VERSION" > exec-version.txt'
  - path: "$PROV"
    phase: release
    args:
      push_branch: "true"
EOF

( cd "$REPO" && "$SEMREL_BIN" release --config .semrel.yaml )

assert_tag_exists "$REPO" "v0.2.0"
assert_file_contains "$REPO/README.md" "version-0.2.0"
assert_file_contains "$REPO/docs/guide.md" "version-0.2.0"
assert_file_contains "$REPO/docs/archive/old.md" "version-0.1.0"
assert_file_contains "$REPO/Dockerfile" "ARG VERSION=0.2.0"
assert_file_contains "$REPO/exec-version.txt" "0.2.0"
assert_file_contains "$REPO/CHANGELOG.md" "exec notes for 0.2.0"

finish
